package main

import "fmt"

func divide(a, b float64) (float64, error) {
    if b == 0 { return 0, fmt.Errorf("divide by zero") }
    return a / b, nil
}

type Account struct {
    ID string
    balance int64
}

func (a *Account) Deposit(cents int64) error {
    if cents <= 0 { return fmt.Errorf("invalid deposit: %d", cents) }
    a.balance += cents
    return nil
}

type UserStore interface {
    Find(ctx context.Context, id string) (User, error)
}

type Service struct { store UserStore }

type Ordered interface { ~int | ~int64 | ~float64 | ~string }

func Min[T Ordered](a, b T) T {
    if a < b { return a }
    return b
}

