group, ctx := errgroup.WithContext(ctx)
for _, job := range jobs {
    job := job
    group.Go(func() error { return process(ctx, job) })
}
if err := group.Wait(); err != nil { return err }

select {
case jobs <- job:
case <-ctx.Done():
    return context.Cause(ctx)
}

