type Cache struct {
    mu sync.RWMutex
    values map[string]Value
}
func (c *Cache) Get(key string) (Value, bool) {
    c.mu.RLock(); defer c.mu.RUnlock()
    value, ok := c.values[key]
    return value, ok
}

